function routeRender(){var k=norm(modeNow());if(k==='grammar'||k==='paragraph')return renderGrammar();D.body.classList.remove('gfActive');return baseRender?baseRender.apply(this,arguments):undefined}
function boot(){installCss();W.setMode=routeSet;W.render=routeRender;try{setMode=W.setMode;render=W.render}catch(e){}D.addEventListener('click',function(e){var t=e.target&&e.target.closest&&e.target.closest('#tabGrammar');if(t){e.preventDefault();e.stopPropagation();renderGrammar()}},true);if(norm(modeNow())==='grammar'||norm(modeNow())==='paragraph')setTimeout(renderGrammar,20)}
